            data["quest_type"],
            data["quest_number"],
            result.get("status"),
        )
        return jsonify(result), 200

    @app.route("/land", methods=["POST"])
    def land_route():
        data = request.get_json(force=True)
        required = ["project", "quest_type", "quest_number"]
        missing = [f for f in required if f not in data]
        if missing:
